# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.models import Student


def make_student(
    last_name, first_name, section, has_email=True
):
    email = None
    if has_email:
        email = first_name.lower() + "@example.invalid"
    student_id = last_name + first_name
    return Student(
        student_id, last_name, first_name, section, email
    )


class ContactRowTests(unittest.TestCase):
    def test_rows_sorted_by_name(self):
        students = [
            make_student("Varrow", "Ines", "A"),
            make_student("Quillon", "Sefa", "B"),
            make_student("Thistle", "Bram", "A")
        ]
        rows = contact_rows(students)
        leading = [row.split()[0] for row in rows]
        self.assertEqual(
            leading, ["Quillon,", "Thistle,", "Varrow,"]
        )

    def test_columns_line_up(self):
        students = [make_student("Thistle", "Bram", "A")]
        row = contact_rows(students)[0]
        # name is 20 wide, then section is 8
        self.assertEqual(row[21], "A")
        self.assertEqual(row[30:], "bram@example.invalid")

    def test_missing_email_names_the_student(self):
        students = [
            make_student("Thistle", "Bram", "A"),
            make_student(
                "Quillon", "Sefa", "B", has_email=False
            )
        ]
        pattern = "Quillon, Sefa"
        with self.assertRaisesRegex(ValueError, pattern):
            contact_rows(students)

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_rows([])
